('291', '17', 'key_benefits', 'a:8:{i:0;a:1:{s:7:\"benefit\";s:66:\"Bespoke design built for your brand — no templates, no shortcuts\";}i:1;a:1:{s:7:\"benefit\";s:70:\"Conversion-optimised pages that turn visitors into enquiries and sales\";}i:2;a:1:{s:7:\"benefit\";s:70:\"Mobile-first design built for the 75%+ of UAE users browsing on mobile\";}i:3;a:1:{s:7:\"benefit\";s:68:\"SEO-ready architecture from day one — not retrofitted after launch\";}i:4;a:1:{s:7:\"benefit\";s:75:\"WordPress CMS giving your team complete content control without a developer\";}i:5;a:1:{s:7:\"benefit\";s:59:\"Core Web Vitals optimised for top Google performance scores\";}i:6;a:1:{s:7:\"benefit\";s:69:\"Structured data and schema markup for enhanced SERP and AI visibility\";}i:7;a:1:{s:7:\"benefit\";s:70:\"Full CMS training and documentation so your team can manage everything\";}}'),
